function assistantHasPendingToolCalls(content: unknown): boolean {
  if (!Array.isArray(content)) return false;
  return content.some((part: any) =>
    part?.type === "toolCall" &&
    part.__toolResult === undefined &&
    part.__toolDetails === undefined &&
